def _written_terms(terms: Path) -> set[Path]:
    """The watch terms the engine has finished writing.

    The engine writes each terms file beside its final name as `<name>.tmp.<pid>.<thread>`
    and renames it into place, so a listing taken mid-write sees a file that is gone by the
    time it is read.
    """
    if not terms.is_dir():
        return set()
    return {path for path in terms.iterdir() if ".tmp." not in path.name}
